import {buildCadAllocationReport} from '@/lib/operations/cad-allocation-report';
export const id=(n:number)=>`b0000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
const alloc=(statement:number,amount:string,month='2024-01-01')=>({statement_id:id(statement),amount_cad_minor:amount,month,account_name:statement===20?'PRIVATE OTHER MONTH':'=FICTIONAL ACCOUNT()'});
const registration=(n:number,status:string,received:string,allocations:ReturnType<typeof alloc>[])=>({id:id(n),revision:1,bank_reference:'FICTIONAL-BANK-'+n,received_on:'2024-03-01',received_cad_minor:received,evidence_reference:'PRIVATE ORIGINAL',evidence_sha256:'a'.repeat(64),note:'PRIVATE NOTE',prepared_by:id(99),prepared_at:'2024-03-02T00:00:00Z',status,review_note:status==='pending'?null:'PRIVATE REVIEW',reviewed_at:status==='pending'?null:'2024-03-03T00:00:00Z',allocations});
export function reportInput(){return {organizationId:id(1),organizationName:'=FICTIONAL COMPANY()',month:'2024-01-01',generatedAt:'2024-04-01T12:00:00Z',data:{reversal_enabled:true,statement_count:1,payment_count:4,statements:[{id:id(2),account_name:'=FICTIONAL ACCOUNT()',month:'2024-01-01',procurement_cad_minor:'10000',verified_cad_minor:'8000',pending_cad_minor:'1000'}],payments:[{...registration(3,'approved','13000',[alloc(2,'8000'),alloc(20,'5000','2024-02-01')]),reversal_pending:true},registration(4,'pending','1000',[alloc(2,'1000')]),registration(5,'rejected','2000',[alloc(2,'2000')]),{...registration(6,'approved','3000',[alloc(2,'3000')]),reversed:true}]}};}
export const report=()=>buildCadAllocationReport(reportInput())!;
